import React, { Component } from 'react'
import { JobStyleWrapper } from './career.style'
import {
  Row,
  Col,
  Menu,
  Dropdown,
  Button,
  Drawer,
  List

} from 'antd'
import { imageUrls, Section5Content } from './content'

export class JobSearchBar extends Component {
  constructor (props) {
    super(props)
    this.state = {
      position: '',
      category: '',
      location: '',
      filteredData: Section5Content.filter(
        item => item.positionsArray.length !== 0
      ),
      modalVisible: false,
      placement: 'bottom',
      visible: false
    }
  }

  positionHandler = ({ key }) => {
    this.setState({
      position: key
    })
  };

  categoryHandler = ({ key }) => {
    this.setState({
      category: key
    })
  };

  locationHandler = ({ key }) => {
    this.setState({
      location: key
    })
  };
  resetCountry = () => {
    this.setState({
      location: ''
    })
  };
  resetCategory = () => {
    this.setState({
      category: ''
    })
  };
  searchedData = (position, category, location) => {
    let allResults = this.state.filteredData
    let finalResults = []

    if (category !== '') {
      allResults = allResults.filter(item => item.category === category)
    }
    finalResults = allResults
    let positionArray = []

    if (position !== '') {
      finalResults.map(item => {
        let array = item['positionsArray'].filter(y => y.position === position)
        if (array.length > 0) {
          let newObject = {
            logo: item.logo,
            category: item.category,
            positionsArray: array
          }
          positionArray.push(newObject)
        }
      })
      finalResults = positionArray
    }

    let locationArray = []

    if (location !== '') {
      finalResults.map(item => {
        let array = item['positionsArray'].filter(
          y => y.jobLocation === location
        )
        if (array.length > 0) {
          let newObject = {
            logo: item.logo,
            category: item.category,
            positionsArray: array
          }
          locationArray.push(newObject)
        }
      })
      finalResults = locationArray
    }
    return finalResults
  };

  submitFilter = () => {
    const { position, category, location } = this.state
    let newlyChangedData = this.searchedData(position, category, location)
    this.props.history.push({
      pathname: '/career/job-category',
      state: newlyChangedData
    })
  };

  openModal = () => {
    this.setState({
      visible: true
    })
  };
  handleOk = () => {
    this.setState({
      visible: false
    })
  };

  handleCancel = () => {
    this.setState({
      visible: false
    })
  };
  mobileSelectCountry = e => {
    this.setState({
      location: e
    })
  };
  mobileSelectCategory = e => {
    this.setState({
      category: e
    })
  };

  submitMobileFilter = () => {
    this.submitFilter()
    this.handleCancel()
  };
  render () {
    const { position, category, location } = this.state
    const positionList = (
      <Menu onClick={this.positionHandler} className='custom-search-menu'>
        <Menu.Item key='Product Head'>Product Head</Menu.Item>
        <Menu.Item key='UI/UX Designer'>UI/UX Designer</Menu.Item>
        <Menu.Item key='Product Manager'>Product Manager</Menu.Item>
        <Menu.Item key='Senior QA Engineer'>Senior QA Engineer</Menu.Item>
        <Menu.Item key='Backend Engineer'>Backend Engineer</Menu.Item>
        <Menu.Item key='Full Stack Engineer'>Full Stack Engineer</Menu.Item>
        <Menu.Item key='Front End Engineer'>Front End Engineer</Menu.Item>
        <Menu.Item key='DevOps Engineer'>DevOps Engineer</Menu.Item>
        <Menu.Item key='Actuary Manager'>Actuary Manager</Menu.Item>
        <Menu.Item key='Internal Audit Manager'>Internal Audit Manager</Menu.Item>
        <Menu.Item key='Business Manager/Relationship Manager'>Business Manager/Relationship Manager</Menu.Item>
        <Menu.Item key='Business Support / Operations Executive'>Business Support / Operations Executive</Menu.Item>
        <Menu.Item key='Collection Specialist'>Collection Specialist</Menu.Item>
        <Menu.Item key='VP of People'>VP of People</Menu.Item>
      </Menu>
    )
    const menu = (
      <Menu onClick={this.categoryHandler} className='custom-search-menu'>
        <Menu.Item key='Business'>Business</Menu.Item>
        <Menu.Item key='Operations'>Operations</Menu.Item>
        <Menu.Item key='Technology'>Technology</Menu.Item>
        <Menu.Item key='Human Resources'>Human Resources</Menu.Item>
        <Menu.Item key='Legal'>Legal</Menu.Item>
        <Menu.Item key='Agency'>Agency</Menu.Item>
        <Menu.Item key='Marketing Communication' disabled>Marketing Communication</Menu.Item>
        <Menu.Item key='Finance' disabled>Finance</Menu.Item>
      </Menu>
    )
    const menu2 = (
      <Menu onClick={this.locationHandler} className='custom-search-menu'>
        <Menu.Item key='Jakarta, Indonesia'>
          Jakarta, Indonesia
          <img src={imageUrls.indonesia} />
        </Menu.Item>
        <Menu.Item key='India'>
          India
          <img src={imageUrls.india} />
        </Menu.Item>
        <Menu.Item key='Thailand' disabled>
          Thailand
          <img src={imageUrls.thailand} />
        </Menu.Item>
        <Menu.Item key='Vietnam' disabled>
          Vietnam
          <img src={imageUrls.vietnam} />
        </Menu.Item>
      </Menu>
    )

    const countryList = [
      {
        title: 'Jakarta, Indonesia',
        logo: imageUrls.indonesia,
        activeCountry: ''
      },
      {
        title: 'India',
        logo: imageUrls.india,
        activeCountry: ''
      }
      // ,
      // {
      //   title: 'Thailand',
      //   logo: imageUrls.thailand,
      //   activeCountry: ''
      // },
      // {
      //   title: 'Vietnam',
      //   logo: imageUrls.vietnam,
      //   activeCountry: ''
      // }
    ]
    const categoryList = [
      {
        title: 'Business'
      },
      {
        title: 'Operations'
      },
      {
        title: 'Technology'
      },
      {
        title: 'Human Resources'
      },
      {
        title: 'Legal'
      },
      {
        title: 'Agency'
      }
      // ,
      // {
      //   title: 'Marketing Communication'
      // },
      // {
      //   title: 'Finance'
      // }
    ]

    return (
      <JobStyleWrapper>
        <Drawer
          placement={this.state.placement}
          closable={false}
          visible={this.state.visible}
          maskClosable='true'
          className='custom-modal-filter custom-close-option'
        >
          <div className='text-center'>
            <span className='close-bar' onClick={() => this.handleCancel} />
          </div>
          <div className='mb-25'>
            <Row justify='space-between' type='flex'>
              <Col>
                <h3>Countries</h3>
              </Col>
              <Col
                className='reset-button'
                onClick={() => this.mobileSelectCountry('')}
              >
                Reset
              </Col>
            </Row>
            <hr className='yellow-divider' />
            <List
              itemLayout='horizontal'
              dataSource={countryList}
              renderItem={(item, index) => (
                <List.Item>
                  <List.Item.Meta
                    onClick={() => this.mobileSelectCountry(item.title)}
                    avatar={<img src={item.logo} width='20px' />}
                    title={item.title}
                  />
                  {location === item.title && (
                    <div>
                      <img src={imageUrls.SelectedIcon} width='20px' />
                    </div>
                  )}
                </List.Item>
              )}
            />
          </div>
          <div className='mb-25'>
            <Row justify='space-between' type='flex'>
              <Col>
                <h3>Categories</h3>
              </Col>
              <Col
                className='reset-button'
                onClick={() => this.mobileSelectCategory('')}
              >
                Reset
              </Col>
            </Row>
            <hr className='yellow-divider' />
            <List
              itemLayout='horizontal'
              dataSource={categoryList}
              renderItem={(item, index) => (
                <List.Item>
                  <List.Item.Meta
                    onClick={() => this.mobileSelectCategory(item.title)}
                    title={item.title}
                  />
                  {category === item.title && (
                    <div>
                      <img src={imageUrls.SelectedIcon} width='20px' />
                    </div>
                  )}
                </List.Item>
              )}
            />
          </div>
          <Row type='flex' justify='space-between'>
            <Col span={12} className='paddingLR10'>
              <Button
                onClick={this.handleCancel}
                className='cancel-button btn-lg'
              >
                <b>Cancel</b>
              </Button>
            </Col>
            <Col span={12} className='paddingLR10'>
              <Button
                onClick={this.submitMobileFilter}
                className='apply-button btn-lg'
              >
                Ok
              </Button>
            </Col>
          </Row>
        </Drawer>
        <Row className={this.props.showBackground ? 'sectionDiv bg-yellow head-shadow display-desktop' : 'sectionDiv head-shadow display-desktop loaded'}>
          <Col
            span={24}
            className='borderR-50 bg-white padding10 searchbar-container display-flex'
          >
            <Col className='border-on flex4 flex-container'>
              <span className='side-image paddingL10'>
                <img src={imageUrls.search} className='small-side-image' />
              </span>
              <Dropdown overlay={positionList}>
                <Button className='input-custom no-padding'>
                  {position !== '' ? position : 'Your Dream Jobs...'}
                </Button>
              </Dropdown>
              {/* <AutoComplete style={{ width: 120 }} dropdownMenuStyle={{ maxHeight: 1000, overflowY: 'visible' }} onChange={handleChange}>
                {opsList}
              </AutoComplete> */}
            </Col>
            <Col className='border-on flex3 positionR'>
              <span className='side-image position-absolute'>
                <img src={imageUrls.country} className='small-side-image' />
              </span>
              <Dropdown overlay={menu2}>
                <Button className='input-custom'>
                  {location !== '' ? location : 'All Countries'}
                </Button>
              </Dropdown>
            </Col>
            <Col className='border-on flex3 positionR'>
              <span className='side-image position-absolute'>
                <img src={imageUrls.category} className='small-side-image' />
              </span>
              <Dropdown overlay={menu}>
                <Button className='input-custom'>
                  {category !== '' ? category : 'Categories'}
                </Button>
              </Dropdown>
            </Col>
            <Col className='flex1'>
              <Button className='enter-button' onClick={this.submitFilter}>
                <img src={imageUrls.enter} className='small-side-image' />
              </Button>
            </Col>
          </Col>
        </Row>
        <Row className='sectionDiv bg-yellow head-shadow display-mobile display-flex align-center'>
          <Col
            span={21}
            className='borderR-50 bg-white padding10 searchbar-container display-flex'
          >
            <Col className='flex-container mobile-search-auto'>
              <span className='side-image mobile-side-image paddingL10'>
                <img src={imageUrls.search} className='small-side-image' />
              </span>
              <Dropdown overlay={positionList}>
                <Button className='input-custom no-padding'>
                  {position !== '' ? position : 'Your Dream Jobs...'}
                </Button>
              </Dropdown>
            </Col>
            <Col>
              <Button
                className='enter-button no-mobile-padding'
                onClick={this.submitFilter}
              >
                <img src={imageUrls.enter} className='small-side-image' />
              </Button>
            </Col>
          </Col>
          <Col span={3}>
            <div className='filter-button text-center' onClick={this.openModal}>
              <img src={imageUrls.filter} className='small-side-image' />
            </div>
          </Col>
        </Row>
      </JobStyleWrapper>
    )
  }
}

export default JobSearchBar
