import React, { Component } from 'react'
import { Row, Col, Breadcrumb, Card, Carousel, Drawer } from 'antd'
import { JobDescription, JobStyleWrapper } from './career.style'
import PropTypes from 'prop-types'
import JobSearchBar from './JobSearchBar'
import { Section5Content, Section4Content, imageUrls } from './content'
import AppFooter from '../../../components/Footer/footer'
export class JobDescriptionComponent extends Component {
  constructor (props) {
    super(props)
    this.state = {
      visible: false,
      placement: 'bottom',
      content: this.props.location.state
    }
  }
  componentWillMount () {
    const { location } = this.props
    const { state } = location
    if (state === undefined) {
      this.homePage()
      window.location.reload()
    }
  }
  homePage = () => {
    this.props.history.push({
      pathname: '/career'
    })
  }
  componentDidMount () {
    window.scrollTo(0, 0)
    // const { location, history } = this.props
    // console.log(this.props)
    // const { state } = location
    // if (state === undefined) {
    //   history.push('/career')
    //   window.location.reload()
    // } else {
    //   const { location } = this.props
    //   this.setState({
    //     content: location.state
    //   })
    // }
  }

  applyFormPage = item => {
    this.props.history.push('/career/form', { ...item })
  };
  careerPage = () => {
    this.props.history.push({
      pathname: '/career'
    })
  }

  categoryPage = () => {
    this.props.history.push({
      pathname: '/career/job-category',
      state: Section5Content.filter(item => item.positionsArray.length > 0)
    })
  }

  vaccanyPage = (index) => {
    const selectedJob = Section5Content.filter(item => item.category === Section4Content[index].text)[0]
    this.props.history.push({
      pathname: '/career/vacancy-list',
      state: { ...selectedJob }
    })
  }

  showModal = () => {
    this.setState({
      visible: true
    })
  };
  handleCancel = e => {
    this.setState({
      visible: false
    })
  };

  handleOk = e => {
    this.setState({
      visible: false
    })
  };
  changePositionDescription = (selectedPosition) => {
    let data = {}
    Section5Content.map((item, index) => {
      let { positionsArray } = item
      positionsArray.map(filterData => {
        if (filterData.position === selectedPosition.position) {
          data = {
            index,
            item,
            filterData
          }
        }
      })
    })
    this.setState({
      content: data
    }, () => {
      window.scrollTo(0, 0)
    })
  }
  render () {
    const { content } = this.state
    const { history } = this.props
    const selectedPosition = content.filterData
    const position = content.item
    const relatedJobs = !!position && position.positionsArray.filter(item => item.position !== selectedPosition.position)
    const positionIndex = content.index

    return (
      <div>
        <JobStyleWrapper>
          <Drawer
            placement={this.state.placement}
            closable={false}
            visible={this.state.visible}
            maskClosable='true'
            className='custom-close-option custom-model-drawer2'
          >
            <div>
              <div className='text-center'>
                <span className='close-bar' onClick={this.handleCancel} />
              </div>
              <Row justify='space-between' type='flex'>
                <Col>
                  <h3>Share</h3>
                </Col>
              </Row>
              <hr className='yellow-divider' />
              <Row
                type='flex'
                justify='space-between'
                className='social-media-icon'
              >
                <Col>
                  <img src={imageUrls.facebook} />
                </Col>
                <Col>
                  <img src={imageUrls.twitter} />
                </Col>
                <Col>
                  <img src={imageUrls.emailYellow} />
                </Col>
                <Col>
                  <img src={imageUrls.whatsapp} />
                </Col>
              </Row>
            </div>
          </Drawer>

          <JobSearchBar history={history} showBackground />
          <JobDescription>
            <Breadcrumb className='padding20 font-size17'>
              <Breadcrumb.Item>
                <span onClick={() => this.careerPage()}>
                  Career
                </span>
              </Breadcrumb.Item>
              <Breadcrumb.Item>
                <span onClick={() => this.categoryPage()}>
                  Jobs
                </span>
              </Breadcrumb.Item>
              <Breadcrumb.Item>
                <span onClick={() => this.vaccanyPage(positionIndex)}>
                  {position.category}
                </span>
              </Breadcrumb.Item>
              <Breadcrumb.Item>
                <span className='text-yellow'>{selectedPosition.position}</span>
              </Breadcrumb.Item>
            </Breadcrumb>
            <Row className='bg-white padding20 marginB70'>
              <Col xl={6} lg={7} md={8} sm={24} xs={24} className='padding20'>
                {/* <div className='display-mobile floatR' onClick={this.showModal}>
                <img src={imageUrls.share} width='15px' />
              </div> */}
                <div className='main-image marginB70 marginT70 mobile-text-center'>
                  <img
                    src={position.logo}
                    alt='logo'
                    className='jobDetail-main-image'
                  />
                </div>
                <div className='marginB70'>
                  <h2 className='text-yellow mobile-text-center'>
                    {selectedPosition.position}
                  </h2>
                  <div className='mobile-flex'>
                    <p className='marginB20 mobile-text-center'>
                      <img
                        src={imageUrls.category}
                        className='smaller-side-image vertical-middle'
                      />
                      <span className='display_inlineB color-fade'>
                        {selectedPosition.position}
                      </span>
                    </p>
                    <p className='marginB20 mobile-text-center'>
                      <img
                        src={imageUrls.jobType}
                        className='smaller-side-image vertical-middle'
                      />
                      <span className='display_inlineB color-fade'>
                        {selectedPosition.jobSpan}
                      </span>
                    </p>
                    <p className='marginB20 mobile-text-center'>
                      <img
                        src={imageUrls.location}
                        className='smaller-side-image vertical-middle'
                      />
                      <span className='display_inlineB color-fade'>
                        {selectedPosition.jobLocation}
                      </span>
                    </p>
                  </div>
                </div>
                {/* <h3 className='text-yellow display-desktop'>Share</h3>
              <div className='social-media-icon display-desktop'>
                <span>
                  <img src={imageUrls.facebook} />
                </span>
                <span>
                  <img src={imageUrls.twitter} />
                </span>
                <span>
                  <img src={imageUrls.emailYellow} />
                </span>
                <span>
                  <img src={imageUrls.whatsapp} />
                </span>
              </div> */}
              </Col>
              <Col xl={18} lg={17} md={16} sm={24} xs={24}>
                {selectedPosition.companyDescription &&
                  <React.Fragment>
                    <h3 className='text-yellow'>Company Description</h3>
                    <div>
                      <p className='customP'>{selectedPosition.companyDescription.heading}</p>
                      <ol className='custom-list line-height2'>
                        {
                          selectedPosition.companyDescription.point.map(d => (
                            <li>{d}</li>
                          ))
                        }
                      </ol>
                      <p className='customP'>
                        {selectedPosition.companyDescription.footer}
                      </p>
                    </div>
                    <hr className='custon-hr' />
                  </React.Fragment>
                }
                <h3 className='text-yellow'>Job Description</h3>
                <ul className='custom-list line-height2'>
                  {selectedPosition.jobDescription.map(item => (
                    <li>{item}</li>
                  ))}
                </ul>
                <hr className='custon-hr' />
                <h3 className='text-yellow'>Minimum Qualifications</h3>
                <ul className='custom-list line-height2'>
                  {selectedPosition.minimumQalification.map(item => (
                    <li>{item}</li>
                  ))}
                </ul>
                <hr className='custon-hr' />
                {
                  selectedPosition.requiredSkills &&
                  <React.Fragment>
                    <h3 className='text-yellow'>Required Skills</h3>
                    <ul className='custom-list'>
                      {selectedPosition.requiredSkills.map(item => (
                        <li>{item}</li>
                      ))}
                    </ul>
                    <hr className='custon-hr' />
                  </React.Fragment>
                }
                <Row>
                  <Col xl={6} lg={6} md={8} sm={12} xs={24}>
                    <div>
                      <button
                        className='btn btn-apply btn-block mobile-round-button'
                        onClick={() => this.applyFormPage(selectedPosition)}
                      >
                        Apply
                      </button>
                    </div>
                  </Col>
                </Row>
              </Col>
            </Row>
            {relatedJobs.length > 0 && (
              <Row className='bg-white padding20'>
                <Col span={24} className='padding20'>
                  <h2 className='text-yellow'>Related Jobs</h2>
                  <p>Not your field? What about these other roles?</p>
                </Col>
                <Col span={24}>
                  <Row className='display-desktop'>
                    {relatedJobs.map(item => (
                      <Col
                        xl={12}
                        lg={12}
                        md={24}
                        sm={24}
                        xs={24}
                        className='padding20'
                      >
                        <Card className='custom-card2'>
                          <Row type='flex' align='center'>
                            <Col span={16} className='padding10'>
                              <h3 className='text-yellow'>{item.position}</h3>
                              <div className='flex-container'>
                                <div className='padding5'>
                                  <img
                                    src={imageUrls.country}
                                    alt='location'
                                    className='display_inlineB smaller-side-image'
                                  />
                                  <small className='display_inlineB color-fade'>
                                    {item.jobLocation}
                                  </small>
                                </div>
                                <div className='padding5'>
                                  <img
                                    src={imageUrls.jobType}
                                    alt='type'
                                    className='display_inlineB smaller-side-image'
                                  />
                                  <small className='display_inlineB color-fade'>
                                    {item.jobSpan}
                                  </small>
                                </div>
                              </div>
                            </Col>
                            <Col span={8} className='padding10'>
                              <div
                                className='text-center job-detail-button button-detail borderR-5'
                                onClick={() => this.changePositionDescription(item)}
                              >
                                Learn More
                              </div>
                            </Col>
                          </Row>
                        </Card>
                      </Col>
                    ))}
                  </Row>
                  <Row className='display-mobile'>
                    <Col span={24}>
                      <Carousel>
                        {relatedJobs.map(item => (
                          <div className='padding20'>
                            <Card
                              className='custom-card mobile-marginB-30'
                              onClick={() => this.changePositionDescription(item)}
                            >
                              <Row type='flex' align='center'>
                                <Col span={24} className='padding10'>
                                  <h3 className='text-yellow'>{item.position}</h3>
                                  <div className='flex-container'>
                                    <div className='padding5'>
                                      <img
                                        src={imageUrls.country}
                                        alt='location'
                                        className='display_inlineB smaller-side-image'
                                      />
                                      <small className='display_inlineB color-fade'>
                                        {' '}
                                        {item.jobLocation}{' '}
                                      </small>
                                    </div>
                                    <div className='padding5'>
                                      <img
                                        src={imageUrls.jobType}
                                        alt='type'
                                        className='display_inlineB smaller-side-image'
                                      />
                                      <small className='display_inlineB color-fade'>
                                        {item.jobSpan}{' '}
                                      </small>
                                    </div>
                                  </div>
                                </Col>
                              </Row>
                            </Card>
                          </div>
                        ))}
                      </Carousel>
                    </Col>
                  </Row>
                </Col>
              </Row>
            )}
          </JobDescription>
        </JobStyleWrapper>
        <AppFooter />
      </div>
    )
  }
}
JobDescriptionComponent.propTypes = {
  sectedContentData: PropTypes.array.isRequired,
  history: PropTypes.object,
  routingFunction: PropTypes.func.isRequired
}
export default JobDescriptionComponent
